export const meta = {
  name: 'orva-codebase-analysis',
  description: 'Deep parallel analysis of the Orva FaaS codebase: product, backend, execution engine, data, AI/MCP, security, frontend, CLI, CI/CD, tests',
  phases: [
    { title: 'Read', detail: 'one agent per subsystem, reading real source' },
    { title: 'Verify', detail: 'cross-check docs claims against code + trace two end-to-end paths' },
  ],
}

const REPORT_SCHEMA = {
  type: 'object',
  properties: {
    subsystem: { type: 'string' },
    purpose: { type: 'string', description: '2-4 sentences: what this subsystem is for' },
    keyFiles: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          path: { type: 'string' },
          role: { type: 'string' },
        },
        required: ['path', 'role'],
      },
      description: '5-15 most important files with one-line role each, repo-relative paths',
    },
    howItWorks: {
      type: 'array',
      items: { type: 'string' },
      description: '6-15 concrete mechanism bullets. Name real functions/types/files. No vague filler.',
    },
    entryPoints: { type: 'array', items: { type: 'string' }, description: 'Where control enters this subsystem (funcs, routes, commands)' },
    dataFlow: { type: 'string', description: 'End-to-end flow through this subsystem, arrow notation' },
    gotchas: { type: 'array', items: { type: 'string' }, description: 'Non-obvious constraints, footguns, coupling a new contributor would trip on' },
    stats: { type: 'string', description: 'Rough size: file count, notable LOC hotspots' },
  },
  required: ['subsystem', 'purpose', 'keyFiles', 'howItWorks', 'entryPoints', 'dataFlow', 'gotchas'],
}

const ROOT = '/home/dev/Orva'

const PREAMBLE = `You are analyzing the Orva codebase at ${ROOT} (a self-hosted Function-as-a-Service platform in Go + Vue).
Read ACTUAL SOURCE FILES — do not rely on docs alone; docs may be stale. Open the real files, read the important ones fully.
Be concrete: name real functions, types, routes, tables, env vars, file paths. Repo-relative paths only.
Your final output is structured data consumed by another agent, not a human message. No preamble, no pleasantries.`

const AREAS = [
  {
    key: 'product-docs',
    prompt: `${PREAMBLE}

AREA: Product definition & documentation set.
Read: README.md, PRODUCT.md, DESIGN.md, docs/reference.md, docs/ARCHITECTURE.md, docs/CLAUDE.md, and skim the remaining docs/*.md (API, CLI, CONFIG, DEPLOYMENT, OPERATIONS, RUNTIMES, SECURITY, CAPACITY, ERRORS, TRACING, GVISOR, KATA, SUPPORT, CONTRIBUTING).
Answer: What IS this product, who is it for, what is the complete user-facing feature list, what are the stated design principles/non-goals, what does each docs/*.md cover, and what is the documented architecture (as claimed). Note the license.
In 'gotchas' list documentation-system rules (e.g. single-source docs, embed steps) and any doc that looks stale vs the repo layout you can see.`,
  },
  {
    key: 'server-http',
    prompt: `${PREAMBLE}

AREA: HTTP server, routing, handlers, middleware, auth, events/SSE.
Read: backend/CLAUDE.md, backend/cmd/orva/*.go, backend/internal/server/server.go, router.go, middleware.go, middleware_auth.go, ui.go, backend/internal/server/handlers/*.go (read routes.go, functions.go, invoke.go, invoke_auth.go, system.go fully; skim the rest), backend/internal/server/events/*.go, backend/internal/auth/principal.go.
Answer: full route table (method + path + handler + auth requirement), how auth works (sessions, API keys, OAuth bearer, principals/scopes), middleware chain order, how the embedded UI is served/SPA-fallback, how SSE/event hub fanout works, error mapping conventions (errmap.go, respond/).
Give the route table compactly inside howItWorks or dataFlow — group by resource.`,
  },
  {
    key: 'execution-engine',
    prompt: `${PREAMBLE}

AREA: The function execution engine — the heart of the product.
Read: backend/internal/sandbox/*.go (sandbox.go, worker.go, seccomp.go, limiter.go), backend/internal/pool/*.go (pool.go, function_pool.go, autoscaler.go, hostmem.go), backend/internal/proxy/*.go, backend/internal/builder/*.go, backend/internal/registry/registry.go, backend/internal/scheduler/scheduler.go, backend/runtimes/ (list and read the node + python adapter sources).
Answer precisely: what happens from an incoming invoke request to a response — pool checkout, nsjail command construction, seccomp policy, cgroup/rlimit enforcement, warm vs cold start, the runtime adapter protocol (how the Go side talks to the node/python process — stdio? unix socket? HTTP?), log capture/parsing, timeouts, concurrency limits, autoscaling policy, build/deploy pipeline (versions, activation, GC), and the cron/scheduler path.
This is the most important area — be exhaustive in howItWorks (15+ bullets is fine).`,
  },
  {
    key: 'data-layer',
    prompt: `${PREAMBLE}

AREA: Persistence and state.
Read: backend/internal/database/*.go — especially database.go, migrations.go, functions.go, executions.go, deployments.go, kv.go, secrets.go, spans.go, jobs.go, cron.go, log_entries.go, async.go, users.go, keys.go, sysconfig.go, migrate_to_uuidv7.go — plus backend/internal/backup/backup.go, backend/internal/ids/ or internal/ids/, backend/internal/metrics/*.go, backend/internal/trace/trace.go.
Answer: the full logical schema (every table + its purpose + key columns), how migrations are declared/run/versioned, SQLite settings (WAL, busy timeout, connection limits), the async write path, retention/GC of executions+logs+spans, the KV store semantics, secret storage & encryption, backup/restore format, ID scheme (UUIDv7) and the migration to it, and how metrics/tracing data is recorded.
List every table you find in keyFiles-style detail inside howItWorks.`,
  },
  {
    key: 'ai-mcp',
    prompt: `${PREAMBLE}

AREA: AI assistant + MCP server (the in-product agent).
Read: backend/internal/ai/manager.go, backend/internal/ai/agent/agent.go, backend/internal/ai/llm/*.go, backend/internal/server/ai_handler.go, backend/internal/database/ai_chat.go, and ALL of backend/internal/mcp/*.go (server.go, auth.go, permissions.go, agent_registry.go, resources.go, every tools_*.go — enumerate the complete tool list with names).
Answer: how the AI chat works end-to-end (streaming protocol to the browser, tool-call loop, provider config/BYO keys, the embedded Bifrost gateway, thinking/reasoning support, conversation persistence), and how the MCP server is exposed (transport, auth, scopes/permissions), plus the COMPLETE list of MCP tool names grouped by domain.
Also note anything about provider reset / stream error handling.`,
  },
  {
    key: 'security-net',
    prompt: `${PREAMBLE}

AREA: Security, isolation, networking, OAuth.
Read: backend/internal/firewall/*.go (manager.go, nftables.go, dns.go), backend/internal/oauth/*.go (all: handlers, clients, consent, crypto, metadata, ratelimit, scopes), backend/internal/secrets/secrets.go, backend/internal/sandbox/seccomp.go, backend/internal/server/handlers/keys.go + ratelimit.go + invoke_auth.go, docs/SECURITY.md, and the sandbox-related parts of docs/DEPLOYMENT.md / docs/GVISOR.md / docs/KATA.md.
Answer: the complete threat/isolation model (what nsjail+seccomp actually restricts, what the alternatives gVisor/Kata are for and whether they're implemented or aspirational), the egress firewall design (nftables rules, DNS interception/allowlists, per-function policy), the OAuth 2.1 implementation (which flows, PKCE, dynamic client registration, consent, token crypto, scope model, rate limiting), API-key handling/hashing, secret encryption at rest, and the required host capabilities (NET_ADMIN, /dev/net/tun, pid/cgroup ns).`,
  },
  {
    key: 'frontend',
    prompt: `${PREAMBLE}

AREA: Vue 3 dashboard.
Read: frontend/CLAUDE.md, frontend/package.json, vite.config.*, frontend/src/main.js, App.vue, router/index.js, api/client.js, api/endpoints.js, stores/*.js, components/layout/*, components/common/* (skim), and the views (read Dashboard.vue, Editor.vue, AI.vue, FunctionsList.vue, Settings.vue properly; skim the rest). Also frontend/src/style.css for the design system.
Answer: stack + build tooling, routing map (path → view → purpose), state management (Pinia stores and what each holds), API client conventions (auth, error handling, SSE consumption), the design system (tokens, theming, typography, component primitives), notable UX features (command palette, code editor/CodeMirror or Monaco, diff view, live activity feed, onboarding), and how the built dist is embedded into the Go binary.`,
  },
  {
    key: 'cli-mcp-client',
    prompt: `${PREAMBLE}

AREA: CLI and shared client packages.
Read: cli/CLAUDE.md, cli/cmd/orva/*.go, cli/commands/*.go (enumerate EVERY subcommand with its flags and what it does), internal/client/*.go, internal/ids/*.go, and how backend/cmd/orva wires the same commands.
Answer: the full command tree (command → subcommands → key flags → API endpoint hit), config resolution order (~/.orva/config.yaml, env, flags), how the single-binary/dual-binary split works, output formatting conventions (json/table), and the install-cli script behavior + upgrade path.`,
  },
  {
    key: 'build-ci-release',
    prompt: `${PREAMBLE}

AREA: Build, packaging, CI/CD, release engineering. Be exhaustive and literal — the user specifically asked about the GitHub Actions workflows.
Read: Makefile (every target), Dockerfile, docker-compose.yml, .dockerignore, scripts/CLAUDE.md and every file in scripts/ (install.sh, install-cli.sh, install-cli.ps1, docker entrypoint, systemd unit, OpenRC unit), and ALL of .github/workflows/: ci.yml, e2e.yml, cli-e2e.yml, install-e2e.yml, release.yml, cleanup-ghcr.yml.
For EACH workflow report: triggers, jobs, job dependencies (needs:), runners, matrix, key steps, what it gates on, and artifacts/outputs produced. Explain the "verify on push / ship on tag" split and the release gate job's exact logic, the ghcr pruning, the multi-arch build, ldflags version stamping, and the rootfs tarball artifacts.
Put the per-workflow breakdown in howItWorks with one bullet block per workflow file.`,
  },
  {
    key: 'testing',
    prompt: `${PREAMBLE}

AREA: Testing strategy.
Read: test/CLAUDE.md, test/e2e/CLAUDE.md, the test/ tree (list all files, read the harness/runner and a few representative cases), test/cli/*, test/install/*, and survey the Go *_test.go files (list them by package and describe what each package's tests cover; read a few of the meatier ones).
Answer: what layers of testing exist, how the shell e2e harness works (how it boots a server, fixtures, assertions, cleanup), what cli-e2e and install-e2e cover, what is well covered vs uncovered, and how to run each suite locally.`,
  },
]

phase('Read')
const reports = await parallel(
  AREAS.map(a => () => agent(a.prompt, { label: `read:${a.key}`, phase: 'Read', schema: REPORT_SCHEMA }))
)
const good = reports.filter(Boolean)
log(`${good.length}/${AREAS.length} subsystem reports returned`)

const digest = good.map(r => `### ${r.subsystem}
PURPOSE: ${r.purpose}
FLOW: ${r.dataFlow}
MECHANISM:
${(r.howItWorks || []).map(b => '- ' + b).join('\n')}
GOTCHAS:
${(r.gotchas || []).map(b => '- ' + b).join('\n')}`).join('\n\n')

phase('Verify')
const VERIFY_SCHEMA = {
  type: 'object',
  properties: {
    corrections: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          claim: { type: 'string' },
          verdict: { type: 'string', enum: ['WRONG', 'IMPRECISE', 'CONFIRMED'] },
          evidence: { type: 'string', description: 'file:line and what the code actually does' },
        },
        required: ['claim', 'verdict', 'evidence'],
      },
    },
    additions: { type: 'array', items: { type: 'string' }, description: 'Important facts the readers missed' },
  },
  required: ['corrections', 'additions'],
}

const verifications = await parallel([
  () => agent(`${PREAMBLE}

TASK: Adversarially fact-check the following subsystem digest against the real code. Pick the 12 most load-bearing or most-likely-wrong claims (especially about the sandbox/nsjail mechanics, the runtime adapter protocol, auth, and the CI gate logic) and verify each by opening the cited code. Mark CONFIRMED / IMPRECISE / WRONG with file:line evidence. Do not rubber-stamp — you are rewarded for finding real errors.

DIGEST:
${digest}`, { label: 'verify:factcheck', phase: 'Verify', schema: VERIFY_SCHEMA, effort: 'high' }),

  () => agent(`${PREAMBLE}

TASK: Trace two complete end-to-end paths through the real code and report them as precise call chains with file:line at each hop. Report your findings in 'additions' (one string per hop-chain step is fine; use 'corrections' only if the digest below contradicts what you find).

PATH A — a public HTTP invocation of a deployed function: from the HTTP listener accepting the request, through routing, auth, function lookup, sandbox/pool checkout, adapter handoff, user code execution, response marshalling, execution+log recording, and the SSE event emitted to the dashboard.

PATH B — deploying a new function version from the CLI: from the CLI subcommand, over HTTP, through the handler, validation, build/queue, filesystem layout under the data dir, activation, and what makes the new version live.

DIGEST (for context; verify rather than trust):
${digest}`, { label: 'verify:e2e-paths', phase: 'Verify', schema: VERIFY_SCHEMA, effort: 'high' }),

  () => agent(`${PREAMBLE}

TASK: Completeness critic. Given the digest below, identify what a thorough reader of this repo would still be missing: subsystems or files nobody opened, cross-cutting concerns (config surface, error taxonomy, observability, graceful shutdown, rate limiting, multi-tenancy, upgrade/migration paths), notable dead code or vestigial features, and the areas of highest complexity/risk. Go READ the gaps you identify and report the actual findings in 'additions' — do not merely list what is missing.

DIGEST:
${digest}`, { label: 'verify:gaps', phase: 'Verify', schema: VERIFY_SCHEMA, effort: 'high' }),
])

return {
  reports: good,
  verifications: verifications.filter(Boolean),
}

content.content:
1	package sandbox
2	
3	import (
4		"bytes"
5		"context"
6		"fmt"
7		"log/slog"
8		"os"
9		"os/exec"
10		"path/filepath"
11		"strconv"
12		"strings"
13		"sync"
14		"time"
15	)
16	
17	// Language identifies a supported runtime.
18	type Language string
19	
20	const (
21		// Orva offers exactly two runtimes, latest-stable only: `node` (Node.js 24)
22		// and `python` (Python 3.14). The identifier is generic on purpose — the
23		// concrete version is an implementation detail that tracks latest-stable and
24		// is surfaced only as a display label (see handlers/runtimes.go). Legacy
25		// versioned IDs (node22/node24/python313/python314) are rewritten to these
26		// at startup — see migrations.go.
27		Node   Language = "node"
28		Python Language = "python"
29	)
30	
31	// IsNode reports whether a language is the Node runtime.
32	func (l Language) IsNode() bool { return l == Node }
33	
34	// IsPython reports whether a language is the Python runtime.
35	func (l Language) IsPython() bool { return l == Python }
36	
37	// ExecConfig holds everything needed to run user code in nsjail.
38	type ExecConfig struct {
39		Language  Language
40		CodeDir   string // Directory containing user code
41		Stdin     []byte // Request JSON piped to stdin
42		Timeout   time.Duration
43		MemoryMB  int
44		MaxPids   int
45		MaxCPUs   float64 // 0 = no cpu cap; positive = fractional CPUs allowed (e.g. 0.5)
46	
47		// Env holds environment variables injected into the sandbox. Includes
48		// both function config env_vars and decrypted secrets at invoke time.
49		Env map[string]string
50	
51		// Seccomp policy (Kafel string). Empty means no seccomp filter.
52		SeccompPolicy string
53	
54		// NetworkMode controls the sandbox's network access. "" or "none"
55		// keeps the function in an isolated net namespace with only loopback
56		// (the safe default — blocks egress and exfil). "egress" adds nsjail's
57		// --use_pasta flag, which gives the sandbox a userspace TCP/UDP stack
58		// that NATs out via the host without exposing host interfaces.
59		NetworkMode string
60	
61		// ResolvConfPath, when non-empty AND NetworkMode=="egress", is the
62		// path of an operator-managed resolv.conf bind-mounted into the
63		// sandbox at /etc/resolv.conf. Generated by the firewall manager
64		// from system_config.dns_servers. Empty falls back to whatever the
65		// rootfs ships (usually nothing meaningful for slim images).
66		ResolvConfPath string
67	
68		// HostsPath, when non-empty AND NetworkMode=="egress", is bind-mounted
69		// at /etc/hosts so operator-defined host→IP overrides take precedence
70		// over upstream DNS. Generated by the firewall manager from
71		// system_config.dns_records.
72		HostsPath string
73	
74		// Paths (populated from config at startup).
75		NsjailBin string
76		RootfsDir string // e.g. ~/.orva/rootfs
77	}
78	
79	// ExecResult holds the outcome of a sandboxed execution.
80	type ExecResult struct {
81		Stdout   []byte
82		Stderr   []byte
83		ExitCode int
84		Duration time.Duration
85		TimedOut bool
86		Error    error
87	}
88	
89	// Execute runs user code inside an nsjail sandbox. Each call spawns a
90	// fresh process — no daemon, no pool.
91	func Execute(ctx context.Context, cfg ExecConfig) *ExecResult {
92		start := time.Now()
93	
94		if cfg.Timeout == 0 {
95			cfg.Timeout = 30 * time.Second
96		}
97		if cfg.MemoryMB == 0 {
98			cfg.MemoryMB = 64
99		}
100		if cfg.MaxPids == 0 {
101			cfg.MaxPids = 32
102		}
103	
104		rootfs, entrypoint, err := resolveRuntime(cfg)
105		if err != nil {
106			return &ExecResult{Error: err, Duration: time.Since(start)}
107		}
108	
109		args := buildArgs(cfg, rootfs, entrypoint)
110	
111		ctx, cancel := context.WithTimeout(ctx, cfg.Timeout+5*time.Second)
112		defer cancel()
113	
114		// nsjail itself carries the required capabilities via setcap (installed
115		// by `orva setup` or baked into the Docker image). No sudo wrapper.
116		cmd := exec.CommandContext(ctx, cfg.NsjailBin, args...)
117	
118		var stdout, stderr bytes.Buffer
119		cmd.Stdout = &stdout
120		cmd.Stderr = &stderr
121		if len(cfg.Stdin) > 0 {
122			cmd.Stdin = bytes.NewReader(cfg.Stdin)
123		}
124	
125		err = cmd.Run()
126	
127		result := &ExecResult{
128			Stdout:   stdout.Bytes(),
129			Stderr:   stderr.Bytes(),
130			Duration: time.Since(start),
131		}
132	
133		if err != nil {
134			if exitErr, ok := err.(*exec.ExitError); ok {
135				result.ExitCode = exitErr.ExitCode()
136			} else {
137				result.Error = err
138			}
139			if ctx.Err() == context.DeadlineExceeded {
140				result.TimedOut = true
141			}
142		}
143	
144		return result
145	}
146	
147	func resolveRuntime(cfg ExecConfig) (rootfs, entrypoint string, err error) {
148		switch cfg.Language {
149		case Python:
150			rootfs = filepath.Join(cfg.RootfsDir, string(cfg.Language))
151			entrypoint = "/usr/local/bin/python3"
152		case Node:
153			rootfs = filepath.Join(cfg.RootfsDir, string(cfg.Language))
154			entrypoint = "/usr/local/bin/node"
155		default:
156			return "", "", fmt.Errorf("unsupported language: %s", cfg.Language)
157		}
158	
159		if _, err := os.Stat(rootfs); err != nil {
160			return "", "", fmt.Errorf("rootfs not found at %s: %w", rootfs, err)
161		}
162		return rootfs, entrypoint, nil
163	}
164	
165	func buildArgs(cfg ExecConfig, rootfs, entrypoint string) []string {
166		// Rely on user namespaces instead of setcap to grant nsjail the caps it
167		// needs for mount/chroot. This works both on bare Linux hosts with
168		// unprivileged_userns_clone=1 AND inside Docker with --cap-add SYS_ADMIN
169		// (where file capabilities don't transfer across fork/exec from a
170		// non-root parent). If you need to force the old setcap-based model
171		// (e.g., kernel has no user namespaces), set ORVA_DISABLE_USERNS=1.
172		//
173		// NOTE: --time_limit intentionally dropped; Go-side context.WithTimeout
174		// + Worker.Kill() handles timeouts with millisecond resolution and
175		// avoids the skew from nsjail's whole-second limit.
176		args := []string{
177			"-Mo",
178			"--chroot", rootfs,
179			"-R", cfg.CodeDir + ":/code",
180			"-T", "/tmp",
181			"--rlimit_as", "max",
182			"-Q",
183		}
184		if os.Getenv("ORVA_DISABLE_USERNS") == "1" {
185			args = append(args, "--disable_clone_newuser")
186		}
187	
188		// Per-function egress. nsjail's default already creates a fresh net
189		// namespace with only loopback; --user_net layers a userspace TCP/UDP
190		// stack (nsjail's bundled "nstun" backend) on top so the function can
191		// reach external APIs without ever touching a host interface.
192		// Functions that don't need network access stay loopback-only —
193		// that's the safe default and blocks data exfiltration from
194		// compromised handlers. Requires /dev/net/tun in the container; the
195		// entrypoint mknods it on startup.
196		if cfg.NetworkMode == "egress" {
197			args = append(args, "--user_net")
198			// Bind-mount the firewall-managed resolv.conf so the function's
199			// DNS resolver matches what the operator configured. nsjail's
200			// -R takes <src>:<dst>; we mount over /etc/resolv.conf inside
201			// the chroot. Skip silently if the file isn't on disk yet — the
202			// firewall manager writes it on its first refresh tick, so a
203			// fresh boot may briefly fall back to the rootfs's default.
204			if cfg.ResolvConfPath != "" {
205				if _, err := os.Stat(cfg.ResolvConfPath); err == nil {
206					args = append(args, "-R", cfg.ResolvConfPath+":/etc/resolv.conf")
207				}
208			}
209			// /etc/hosts overrides — the resolver consults files before DNS by
210			// default, so any host→IP record in this file beats whatever the
211			// upstream resolver returns. Same skip-if-missing posture as resolv.
212			if cfg.HostsPath != "" {
213				if _, err := os.Stat(cfg.HostsPath); err == nil {
214					args = append(args, "-R", cfg.HostsPath+":/etc/hosts")
215				}
216			}
217		}
218	
219		// Cgroup v2 resource limits — only enabled if we have a writable cgroup
220		// delegate (systemd user slice on most modern hosts; bind-mounted in the
221		// Docker image). Without delegation nsjail can't create the NSJAIL.<pid>
222		// cgroup, so rather than crashing we silently drop the memory/pid caps.
223		// The process-level rlimit_as flag above still bounds address-space.
224		if mount := cgroupv2Delegate(); mount != "" {
225			// cgroup v2 memory.max at 1.5× the declared memory. This gives the
226			// kernel headroom to reclaim via PSI pressure before OOM-killing,
227			// and matches the 1.5× per-worker budget the autoscaler uses for
228			// admission control.
229			memMaxBytes := int64(cfg.MemoryMB) * 1024 * 1024 * 3 / 2
230			args = append(args,
231				"--use_cgroupv2",
232				"--cgroupv2_mount", mount,
233				"--cgroup_mem_max", fmt.Sprintf("%d", memMaxBytes),
234				"--cgroup_pids_max", fmt.Sprintf("%d", cfg.MaxPids),
235			)
236			// Use cgroup CPU bandwidth (cpu.max) instead of --max_cpus. The
237			// --max_cpus flag is an affinity mask that pins the process to a
238			// subset of cores — actively harmful under concurrency because the
239			// kernel can't load-balance across the full CPU set. Bandwidth
240			// limits (microseconds per period) are what fractional CPU means.
241			if msPerSec := int(cfg.MaxCPUs * 1000); msPerSec > 0 {
242				// nsjail --cgroup_cpu_ms_per_sec = ms of CPU per 1000 ms window.
243				// Supports fractional CPUs: 0.5 → 500, 0.25 → 250.
244				args = append(args,
245					"--cgroup_cpu_ms_per_sec",
246					fmt.Sprintf("%d", msPerSec),
247				)
248			}
249		}
250	
251		if cfg.SeccompPolicy != "" {
252			args = append(args, "--seccomp_string", cfg.SeccompPolicy)
253		}
254	
255		// Inject env vars + secrets. nsjail takes --env KEY=VAL; an --env with
256		// no '=' passes the host-side value through, which we never want for
257		// security. Always format as KEY=VAL explicitly.
258		for k, v := range cfg.Env {
259			if k == "" {
260				continue
261			}
262			args = append(args, "--env", k+"="+v)
263		}
264		// Also tell the Python/Node adapter about Orva context via env.
265		args = append(args,
266			"--env", "ORVA_FUNCTION_ID="+getenvOr(cfg.Env, "ORVA_FUNCTION_ID", ""),
267			"--env", "ORVA_EXECUTION_ID="+getenvOr(cfg.Env, "ORVA_EXECUTION_ID", ""),
268		)
269	
270		args = append(args, "--", entrypoint)
271	
272		switch {
273		case cfg.Language.IsPython():
274			args = append(args, "/opt/orva/adapter.py")
275		case cfg.Language.IsNode():
