package server

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"path/filepath"
	"testing"

	"github.com/Harsh-2002/Orva/backend/internal/config"
	"github.com/Harsh-2002/Orva/backend/internal/database"
	"github.com/Harsh-2002/Orva/backend/internal/registry"
	"github.com/Harsh-2002/Orva/backend/internal/version"
)

// testContext holds a test server and a valid admin API key.
type testContext struct {
	srv    *Server
	apiKey string
}

func newTestServer(t *testing.T) *testContext {
	t.Helper()
	dir := t.TempDir()
	cfg := config.Defaults()
	cfg.Database.Path = filepath.Join(dir, "test.db")
	// Hermetic: keep version trees, .admin-key, and any other per-server
	// state inside the test's tempdir instead of bleeding to ~/.orva.
	cfg.Data.Dir = dir

	db, err := database.New(cfg.Database.Path)
	if err != nil {
		t.Fatal(err)
	}
	if err := db.Migrate(); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { db.Close() })

	// Insert a known admin key for testing before creating the server
	// so the bootstrap logic doesn't print to stdout.
	testKey := "REDACTED"
	hash := sha256.Sum256([]byte(testKey))
	keyHash := hex.EncodeToString(hash[:])
	testAPIKey := &database.APIKey{
		ID:          "key_testadmin01",
		KeyHash:     keyHash,
		Name:        "test-admin",
		Permissions: `["invoke","read","write","admin"]`,
	}
	if err := db.InsertAPIKey(testAPIKey); err != nil {
		t.Fatal(err)
	}

	srv := New(cfg, db)

	return &testContext{
		srv:    srv,
		apiKey: testKey,
	}
}

// setAuth sets the X-Orva-API-Key header on a request.
func (tc *testContext) setAuth(req *http.Request) {
	req.Header.Set("X-Orva-API-Key", tc.apiKey)
}

func TestHealthEndpoint(t *testing.T) {
	tc := newTestServer(t)

	req := httptest.NewRequest("GET", "/api/v1/system/health", nil)
	w := httptest.NewRecorder()
	tc.srv.router.ServeHTTP(w, req)

	if w.Code != 200 {
		t.Errorf("expected 200, got %d", w.Code)
	}

	var resp map[string]any
	if err := json.NewDecoder(w.Body).Decode(&resp); err != nil {
		t.Fatal(err)
	}
	if resp["status"] != "healthy" {
		t.Errorf("expected healthy status, got %v", resp["status"])
	}
	if resp["version"] != version.Version {
		t.Errorf("expected version %s, got %v", version.Version, resp["version"])
	}
}

func TestRequestIDMiddleware(t *testing.T) {
	tc := newTestServer(t)

	req := httptest.NewRequest("GET", "/api/v1/system/health", nil)
	w := httptest.NewRecorder()
	tc.srv.router.ServeHTTP(w, req)

	id := w.Header().Get("X-Request-ID")
	if id == "" {
		t.Error("expected X-Request-ID header")
	}
	if len(id) < 4 {
		t.Errorf("request ID too short: %s", id)
	}
}

