// newServeCmd constructs the `orva serve` subcommand. Server binary only.
func newServeCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "serve",
		Short: "Start the Orva server",
		Long:  "Start the Orva API server and begin accepting requests.",
		Run:   runServe,
	}
