		fmt.Fprintf(out, "Reinstalling orva %s (new build) ...\n", latestStr)
	} else {
		fmt.Fprintf(out, "Upgrading orva %s -> %s ...\n", Version, latestStr)
	}
	if err := downloadVerifyApply(ctx, latest, exe); err != nil {
		return fmt.Errorf("upgrade failed: %w", err)
