func TestDetectLatest(t *testing.T) {
	wantAsset := upgradeAssetName(runtime.GOOS, runtime.GOARCH)

	mux := http.NewServeMux()
	mux.HandleFunc("/repos/acme/orva/releases/latest", func(w http.ResponseWriter, r *http.Request) {
