// Package firewall enforces the global egress blocklist on top of the
// per-function egress toggle. Every function with network_mode='egress'
// goes through nsjail's --user_net (a userspace TCP/UDP stack); the
// firewall package adds two layers on top:
//
//  1. **Hostname matching**: rules of type 'hostname' or 'wildcard' are
//     resolved on a 5-min ticker into IPs that get appended to the
//     effective set.
//  2. **nftables packet filter**: every enabled rule's IPs/CIDRs go
//     into a dedicated nftables set and a chain that DROPs matching
//     egress packets.
//
// Source of truth is the `egress_blocklist` table — UI-driven, not
// config-file-driven. The Manager polls every 10s for table changes
// and applies them live.
package firewall

import (
	"context"
	"errors"
	"log/slog"
	"net"
	"strings"
	"sync"
	"time"

	"github.com/Harsh-2002/Orva/backend/internal/database"
)

// Manager owns the firewall lifecycle. One instance per orvad process.
// Lives for the duration of the server; Stop() drains gracefully.
type Manager struct {
	db      *database.Database
	dataDir string // where the per-sandbox resolv.conf is written

	// Cached effective set of IPv4/IPv6 CIDRs derived from rules.
	// Read by the API for /resolve introspection.
	mu          sync.RWMutex
	resolvedV4  []string // CIDRs ready for nft set
	resolvedV6  []string
	hostnameMap map[string][]string // rule.value → resolved IPs (for UI display)
	lastError   string              // most recent apply or resolve error, surfaced by /firewall/status

	pollInterval    time.Duration
	resolveInterval time.Duration

	stopCh chan struct{}
	wg     sync.WaitGroup
}

func NewManager(db *database.Database, dataDir string) *Manager {
	return &Manager{
		db:              db,
		dataDir:         dataDir,
		hostnameMap:     map[string][]string{},
		pollInterval:    10 * time.Second,
		resolveInterval: 5 * time.Minute,
	}
}

// Start kicks off the poll + resolve goroutines and applies the initial
// rule set. Errors during apply are logged but don't stop the manager —
// the API still works; nftables enforcement just won't be in place.
//
// In environments where nftables is unavailable (tests, hosts without
// NET_ADMIN, BSD), Start short-circuits: the API still answers, but no
// background goroutine runs. This avoids leaking polling goroutines
// across the test process lifetime.
func (m *Manager) Start(ctx context.Context) {
	m.stopCh = make(chan struct{})

	// DNS (resolv.conf + hosts file) is independent of nftables — write
	// both on every boot, even if packet filtering is disabled. Otherwise
	// functions with network_mode=egress on hosts without nftables would
	// lose operator-configured DNS resolvers and host overrides.
	if m.dataDir != "" {
		dnsCfg := LoadDNSConfig(m.db)
		if err := WriteResolvConf(m.dataDir, dnsCfg); err != nil {
			slog.Warn("firewall: initial resolv.conf write failed", "err", err)
		}
		if err := WriteHostsFile(m.dataDir, dnsCfg.Records); err != nil {
			slog.Warn("firewall: initial hosts file write failed", "err", err)
		}
	}

	if !nftablesAvailable() {
		m.setLastError("nftables unavailable: install the 'nftables' package, run 'modprobe nf_tables', and ensure the orva process has CAP_NET_ADMIN. Egress filtering is disabled until this is resolved; the per-function egress toggle still works (sandbox isolation only).")
		slog.Warn("firewall: nftables unavailable — egress filtering disabled",
			"hint", "install nftables, modprobe nf_tables, run with CAP_NET_ADMIN")
		return
	}

	// Initial apply on startup.
	if err := m.refresh(); err != nil {
		slog.Warn("firewall initial apply failed", "err", err)
		m.setLastError(err.Error())
	}

	m.wg.Add(1)
	go m.pollLoop(ctx)
}

func (m *Manager) Stop(ctx context.Context) error {
	close(m.stopCh)
	done := make(chan struct{})
	go func() { m.wg.Wait(); close(done) }()
	select {
	case <-done:
	case <-ctx.Done():
		return ctx.Err()
	}
	// Best-effort cleanup of nftables state. Failures here are noise on
	// shutdown so we just log.
	if err := nftablesFlush(); err != nil {
		slog.Debug("firewall flush on shutdown", "err", err)
	}
	return nil
}

// pollLoop ticks the poll interval (DB changes) and the resolve
// interval (re-resolve hostnames). Combining them in one goroutine
// avoids races on m.resolvedV4/V6.
func (m *Manager) pollLoop(ctx context.Context) {
	defer m.wg.Done()
	pollT := time.NewTicker(m.pollInterval)
	defer pollT.Stop()
	resolveT := time.NewTicker(m.resolveInterval)
	defer resolveT.Stop()

	for {
		select {
		case <-m.stopCh:
			return
		case <-ctx.Done():
			return
		case <-pollT.C:
			if err := m.refresh(); err != nil {
				slog.Warn("firewall refresh failed", "err", err)
				m.setLastError(err.Error())
			}
		case <-resolveT.C:
			if err := m.refresh(); err != nil {
				slog.Warn("firewall resolve failed", "err", err)
				m.setLastError(err.Error())
			}
		}
	}
}

// ForceRefresh is the API hook for "Force resolve now" in the UI.
// Returns whatever apply returned so the operator sees errors live.
func (m *Manager) ForceRefresh() error {
	err := m.refresh()
	if err != nil {
		m.setLastError(err.Error())
	}
	return err
}

// refresh: read enabled rules, expand hostnames to IPs, build set,
// apply nftables. Single goroutine path — no need to lock the apply.
func (m *Manager) refresh() error {
	rules, err := m.db.ListEnabledBlocklistRules()
	if err != nil {
		return err
	}

	v4, v6 := []string{}, []string{}
	hostnameMap := map[string][]string{}

	for _, r := range rules {
		switch r.RuleType {
		case database.BlocklistTypeCIDR:
			if isIPv6CIDR(r.Value) {
				v6 = append(v6, r.Value)
			} else {
				v4 = append(v4, r.Value)
			}
		case database.BlocklistTypeHostname, database.BlocklistTypeWildcard:
			ips := resolveHostnameSet(r.Value)
			hostnameMap[r.Value] = ips
			for _, ip := range ips {
				if strings.Contains(ip, ":") {
					v6 = append(v6, ip+"/128")
				} else {
					v4 = append(v4, ip+"/32")
				}
			}
		}
	}

	m.mu.Lock()
	m.resolvedV4 = dedupe(v4)
	m.resolvedV6 = dedupe(v6)
	m.hostnameMap = hostnameMap
	m.mu.Unlock()

	if err := nftablesApply(m.resolvedV4, m.resolvedV6); err != nil {
		return err
	}

	// Regenerate the per-sandbox resolv.conf + /etc/hosts alongside the
	// nft rules. Both come from operator-driven settings; all three should
	// re-apply on the same tick. Failure here is non-fatal — sandboxes
	// fall back to whatever was last on disk (or the host's if we never
	// wrote one).
	if m.dataDir != "" {
		dnsCfg := LoadDNSConfig(m.db)
		if err := WriteResolvConf(m.dataDir, dnsCfg); err != nil {
			slog.Warn("firewall: write resolv.conf failed", "err", err)
		}
		if err := WriteHostsFile(m.dataDir, dnsCfg.Records); err != nil {
			slog.Warn("firewall: write hosts file failed", "err", err)
		}
	}

	m.setLastError("")
	return nil
}

// Snapshot returns a read-only view of the current effective set.
// Used by the /firewall/status endpoint and the UI's "currently
// resolving to" column.
type Snapshot struct {
	IPv4         []string            `json:"ipv4"`
	IPv6         []string            `json:"ipv6"`
	HostnameMap  map[string][]string `json:"hostname_map"`
	LastError    string              `json:"last_error,omitempty"`
	NftablesAvail bool                `json:"nftables_available"`
}

func (m *Manager) Snapshot() Snapshot {
	m.mu.RLock()
	defer m.mu.RUnlock()
	out := Snapshot{
		IPv4:          append([]string(nil), m.resolvedV4...),
		IPv6:          append([]string(nil), m.resolvedV6...),
		HostnameMap:   map[string][]string{},
		LastError:     m.lastError,
		NftablesAvail: nftablesAvailable(),
	}
	for k, v := range m.hostnameMap {
		out.HostnameMap[k] = append([]string(nil), v...)
	}
	return out
}

func (m *Manager) setLastError(s string) {
	m.mu.Lock()
	m.lastError = s
	m.mu.Unlock()
}

// resolveHostnameSet handles both exact hostnames and *.suffix wildcards.
// Wildcards can't be expanded (we don't enumerate every *.foo.com), so
// for a wildcard we resolve only the suffix's apex — best-effort. The
// nftables layer can't match by hostname, so wildcards primarily protect
// via the DNS layer (future work). Exact hostnames work fully.
func resolveHostnameSet(value string) []string {
	target := value
	if strings.HasPrefix(value, "*.") {
		target = value[2:]
	}
	addrs, err := net.LookupHost(target)
	if err != nil {
		return nil
	}
	return addrs
}

func isIPv6CIDR(s string) bool {
	if !strings.Contains(s, "/") {
		return strings.Contains(s, ":")
	}
	ip, _, err := net.ParseCIDR(s)
	if err != nil {
		return false
	}
	return ip.To4() == nil
}

func dedupe(in []string) []string {
	seen := map[string]bool{}
	out := []string{}
	for _, v := range in {
		if seen[v] {
			continue
		}
		seen[v] = true
		out = append(out, v)
	}
	return out
}

// ErrManagerClosed is returned from API calls after Stop().
var ErrManagerClosed = errors.New("firewall manager closed")

package firewall

import (
	"bytes"
	"errors"
	"fmt"
	"log/slog"
	"os/exec"
	"strings"
	"sync"
	"sync/atomic"
)

// nftables-backed enforcement. The Manager calls nftablesApply with the
// effective IPv4 and IPv6 CIDR sets every refresh. We render a single
// `nft -f -` script that idempotently rebuilds our table — that way we
// never leave stale rules around.
//
// Table layout:
//
//   table inet orva_firewall {
//     set orva_egress_v4 {
//       type ipv4_addr
//       flags interval
//       elements = { ... CIDRs ... }
//     }
//     set orva_egress_v6 {
//       type ipv6_addr
//       flags interval
//       elements = { ... CIDRs ... }
//     }
//     chain output {
//       type filter hook output priority 0;
//       ip  daddr @orva_egress_v4 reject with icmp type host-unreachable
//       ip6 daddr @orva_egress_v6 reject with icmpv6 type addr-unreachable
//     }
//   }
//
// We use `reject` instead of `drop` so handlers see EHOSTUNREACH
// immediately rather than hanging until their own timeout. Easier to
// debug and the operator gets a clean error in the function logs.

const tableName = "orva_firewall"

// nftablesAvail caches whether `nft` is on PATH and works; probed lazily
// the first time nftablesAvailable() is called. If unavailable, Apply
// becomes a no-op and the API surfaces a warning via Snapshot.LastError.
//
// Lazy probe — not init() — so that simply importing this package (e.g.,
// by the CLI which transitively pulls in internal/server) does not run
// nft and emit warnings before the user has even invoked a subcommand.
// The probe still runs at most once per process via nftablesProbeOnce.
var (
	nftablesAvail     atomic.Bool
	nftablesProbeOnce sync.Once
)

func nftablesAvailable() bool {
	nftablesProbeOnce.Do(probeNftables)
	return nftablesAvail.Load()
}

func probeNftables() {
	if _, err := exec.LookPath("nft"); err == nil {
		// Probe: try a no-op list. If we don't have CAP_NET_ADMIN this
		// will fail; that's information we want surfaced to the operator.
		out, err := exec.Command("nft", "list", "tables").CombinedOutput()
		if err == nil {
			nftablesAvail.Store(true)
			_ = out
		} else {
			slog.Warn("nft list failed; firewall enforcement will be disabled",
				"err", err, "output", string(out))
		}
	} else {
		slog.Warn("nft binary not on PATH; firewall enforcement will be disabled")
	}
}

// nftablesApply rebuilds the orva_firewall table with the given sets.
// Idempotent — if nothing changed, the operation is harmless. If the
// sets are empty, the table is created with empty sets so a "deny
// everything matching" chain still exists (matching nothing).
func nftablesApply(v4, v6 []string) error {
	if !nftablesAvailable() {
		return nil // best-effort: silently no-op
	}

	var b bytes.Buffer
	// flush + delete is the pattern that makes `nft -f -` re-runnable
	// without leaking old rules.
	fmt.Fprintf(&b, "delete table inet %s\n", tableName)
	fmt.Fprintf(&b, "table inet %s {\n", tableName)
	fmt.Fprintf(&b, "  set orva_egress_v4 {\n")
	fmt.Fprintf(&b, "    type ipv4_addr\n")
	fmt.Fprintf(&b, "    flags interval\n")
	if len(v4) > 0 {
		fmt.Fprintf(&b, "    elements = { %s }\n", strings.Join(v4, ", "))
	}
	fmt.Fprintf(&b, "  }\n")
	fmt.Fprintf(&b, "  set orva_egress_v6 {\n")
	fmt.Fprintf(&b, "    type ipv6_addr\n")
	fmt.Fprintf(&b, "    flags interval\n")
	if len(v6) > 0 {
		fmt.Fprintf(&b, "    elements = { %s }\n", strings.Join(v6, ", "))
	}
	fmt.Fprintf(&b, "  }\n")
	fmt.Fprintf(&b, "  chain output {\n")
	fmt.Fprintf(&b, "    type filter hook output priority 0;\n")
	fmt.Fprintf(&b, "    oif lo accept\n")
	fmt.Fprintf(&b, "    ip  daddr @orva_egress_v4 reject with icmp type host-unreachable\n")
	fmt.Fprintf(&b, "    ip6 daddr @orva_egress_v6 reject with icmpv6 type addr-unreachable\n")
	fmt.Fprintf(&b, "  }\n")
	fmt.Fprintf(&b, "}\n")

	cmd := exec.Command("nft", "-f", "-")
	cmd.Stdin = &b
	out, err := cmd.CombinedOutput()
	if err != nil {
		// If the delete failed because the table didn't exist, that's
		// fine on first apply — retry without the delete prefix.
		errStr := string(out) + " " + err.Error()
		if strings.Contains(errStr, "No such file or directory") ||
			strings.Contains(errStr, "does not exist") {
			b.Reset()
			fmt.Fprintf(&b, "table inet %s {\n", tableName)
			fmt.Fprintf(&b, "  set orva_egress_v4 { type ipv4_addr; flags interval; %s }\n",
				elementsLine(v4))
			fmt.Fprintf(&b, "  set orva_egress_v6 { type ipv6_addr; flags interval; %s }\n",
				elementsLine(v6))
			fmt.Fprintf(&b, "  chain output { type filter hook output priority 0;\n")
			fmt.Fprintf(&b, "    oif lo accept\n")
			fmt.Fprintf(&b, "    ip  daddr @orva_egress_v4 reject with icmp type host-unreachable\n")
			fmt.Fprintf(&b, "    ip6 daddr @orva_egress_v6 reject with icmpv6 type addr-unreachable\n")
			fmt.Fprintf(&b, "  }\n}\n")
			cmd = exec.Command("nft", "-f", "-")
			cmd.Stdin = &b
			out, err = cmd.CombinedOutput()
			if err != nil {
				return errors.New("nft apply failed: " + strings.TrimSpace(string(out)) + ": " + err.Error())
			}
			return nil
		}
		return errors.New("nft apply failed: " + strings.TrimSpace(string(out)) + ": " + err.Error())
	}
	return nil
}

func elementsLine(items []string) string {
	if len(items) == 0 {
		return ""
	}
	return "elements = { " + strings.Join(items, ", ") + " };"
}

// nftablesFlush is called on shutdown to drop our table.
func nftablesFlush() error {
	if !nftablesAvailable() {
		return nil
	}
	cmd := exec.Command("nft", "delete", "table", "inet", tableName)
	out, err := cmd.CombinedOutput()
	if err != nil && !strings.Contains(string(out), "does not exist") &&
		!strings.Contains(string(out), "No such file") {
		return errors.New(string(out))
	}
	return nil
}

// IsNode reports whether a language is the Node runtime.
func (l Language) IsNode() bool { return l == Node }

// IsPython reports whether a language is the Python runtime.
func (l Language) IsPython() bool { return l == Python }

// ExecConfig holds everything needed to run user code in nsjail.
type ExecConfig struct {
	Language Language
	CodeDir  string // Directory containing user code
	Stdin    []byte // Request JSON piped to stdin
	Timeout  time.Duration
	MemoryMB int
	MaxPids  int
	MaxCPUs  float64 // 0 = no cpu cap; positive = fractional CPUs allowed (e.g. 0.5)

	// Env holds environment variables injected into the sandbox. Includes
	// both function config env_vars and decrypted secrets at invoke time.
	Env map[string]string

	// Seccomp policy (Kafel string). Empty means no seccomp filter.
	SeccompPolicy string

	// NetworkMode controls the sandbox's network access. "" or "none"
	// keeps the function in an isolated net namespace with only loopback
	// (the safe default — blocks egress and exfil). "egress" adds nsjail's
	// --use_pasta flag, which gives the sandbox a userspace TCP/UDP stack
	// that NATs out via the host without exposing host interfaces.
	NetworkMode string

	// ResolvConfPath, when non-empty AND NetworkMode=="egress", is the
	// path of an operator-managed resolv.conf bind-mounted into the
	// sandbox at /etc/resolv.conf. Generated by the firewall manager
	// from system_config.dns_servers. Empty falls back to whatever the
	// rootfs ships (usually nothing meaningful for slim images).
	ResolvConfPath string

	// HostsPath, when non-empty AND NetworkMode=="egress", is bind-mounted
	// at /etc/hosts so operator-defined host→IP overrides take precedence
	// over upstream DNS. Generated by the firewall manager from
	// system_config.dns_records.
	HostsPath string

	// Paths (populated from config at startup).
	NsjailBin string
	RootfsDir string // e.g. ~/.orva/rootfs
}

// ExecResult holds the outcome of a sandboxed execution.
type ExecResult struct {
	Stdout   []byte
	Stderr   []byte
	ExitCode int
	Duration time.Duration
	TimedOut bool
	Error    error
}

// Execute runs user code inside an nsjail sandbox. Each call spawns a
// fresh process — no daemon, no pool.
func Execute(ctx context.Context, cfg ExecConfig) *ExecResult {
	start := time.Now()
	cfg = applyExecDefaults(cfg)

	rootfs, entrypoint, err := resolveRuntime(cfg)
	if err != nil {
		return &ExecResult{Error: err, Duration: time.Since(start)}
	}

	args := buildArgs(cfg, rootfs, entrypoint)

	ctx, cancel := context.WithTimeout(ctx, cfg.Timeout+5*time.Second)
	defer cancel()

	// nsjail itself carries the required capabilities via setcap (installed
	// by `orva setup` or baked into the Docker image). No sudo wrapper.
	cmd := exec.CommandContext(ctx, cfg.NsjailBin, args...)

	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	if len(cfg.Stdin) > 0 {
		cmd.Stdin = bytes.NewReader(cfg.Stdin)
	}

	err = cmd.Run()

	result := &ExecResult{
		Stdout:   stdout.Bytes(),
		Stderr:   stderr.Bytes(),
		Duration: time.Since(start),
	}

	if err != nil {
		if exitErr, ok := err.(*exec.ExitError); ok {
			result.ExitCode = exitErr.ExitCode()
		} else {
			result.Error = err
		}
		if ctx.Err() == context.DeadlineExceeded {
			result.TimedOut = true
		}
	}

	return result
}

// applyExecDefaults is shared by one-shot execution and pooled workers.
// Keeping the defaults in one place is security-sensitive: passing MaxPids=0
// to nsjail's cgroup-v2 flag means "allow zero processes", so every pooled
// worker exits immediately on hosts where cgroup delegation is available.
func applyExecDefaults(cfg ExecConfig) ExecConfig {
	if cfg.Timeout == 0 {
		cfg.Timeout = 30 * time.Second
	}
	if cfg.MemoryMB == 0 {
		cfg.MemoryMB = 64
	}
	if cfg.MaxPids == 0 {

		return "", "", fmt.Errorf("rootfs path is not a directory: %s", rootfs)
	}
	entrypointPath := filepath.Join(rootfs, filepath.FromSlash(strings.TrimPrefix(entrypoint, "/")))
	entrypointInfo, err := os.Stat(entrypointPath)
	if err != nil || entrypointInfo.IsDir() || entrypointInfo.Mode()&0o111 == 0 {
		return "", "", fmt.Errorf("runtime entrypoint is missing or not executable at %s", entrypointPath)
	}
	adapterPath := filepath.Join(rootfs, filepath.FromSlash(strings.TrimPrefix(adapter, "/")))
	adapterInfo, err := os.Stat(adapterPath)
	if err != nil || adapterInfo.IsDir() {
		return "", "", fmt.Errorf("runtime adapter is missing at %s", adapterPath)
	}
	return rootfs, entrypoint, nil
}

func buildArgs(cfg ExecConfig, rootfs, entrypoint string) []string {
	// Prefer user namespaces for nsjail's mount/chroot setup. On hosts that
	// restrict unprivileged user namespaces, the bare-metal installer grants
	// the nsjail executable the narrow capability set it needs and exports
	// ORVA_DISABLE_USERNS=1. Docker keeps the default userns path.
	//
	// NOTE: --time_limit intentionally dropped; Go-side context.WithTimeout
	// + Worker.Kill() handles timeouts with millisecond resolution and
	// avoids the skew from nsjail's whole-second limit.
	args := []string{
		"-Mo",
		"--chroot", rootfs,
		"-R", cfg.CodeDir + ":/code",
		"-T", "/tmp",
		"--rlimit_as", "max",
		"-Q",
	}
	if os.Getenv("ORVA_DISABLE_USERNS") == "1" {
		args = append(args, "--disable_clone_newuser")
	}

	// Per-function egress. nsjail's default already creates a fresh net
	// namespace with only loopback; --user_net layers a userspace TCP/UDP
	// stack (nsjail's bundled "nstun" backend) on top so the function can
	// reach external APIs without ever touching a host interface.
	// Functions that don't need network access stay loopback-only —
	// that's the safe default and blocks data exfiltration from
	// compromised handlers. Requires /dev/net/tun in the container; the
	// entrypoint mknods it on startup.
	if cfg.NetworkMode == "egress" {
		args = append(args, "--user_net")
		// Bind-mount the firewall-managed resolv.conf so the function's
		// DNS resolver matches what the operator configured. nsjail's
		// -R takes <src>:<dst>; we mount over /etc/resolv.conf inside
		// the chroot. Skip silently if the file isn't on disk yet — the
		// firewall manager writes it on its first refresh tick, so a
		// fresh boot may briefly fall back to the rootfs's default.
		if cfg.ResolvConfPath != "" {
			if _, err := os.Stat(cfg.ResolvConfPath); err == nil {
				args = append(args, "-R", cfg.ResolvConfPath+":/etc/resolv.conf")
			}
		}
		// /etc/hosts overrides — the resolver consults files before DNS by
		// default, so any host→IP record in this file beats whatever the
		// upstream resolver returns. Same skip-if-missing posture as resolv.
		if cfg.HostsPath != "" {
			if _, err := os.Stat(cfg.HostsPath); err == nil {
				args = append(args, "-R", cfg.HostsPath+":/etc/hosts")
			}
		}
	}

	// Cgroup v2 resource limits — only enabled if we have a writable cgroup
	// delegate (systemd user slice on most modern hosts; bind-mounted in the
	// Docker image). Without delegation nsjail can't create the NSJAIL.<pid>
	// cgroup, so rather than crashing we silently drop the memory/pid caps.
	// The process-level rlimit_as flag above still bounds address-space.
	if mount := cgroupv2Delegate(); mount != "" {
		// cgroup v2 memory.max at 1.5× the declared memory. This gives the
		// kernel headroom to reclaim via PSI pressure before OOM-killing,
		// and matches the 1.5× per-worker budget the autoscaler uses for
		// admission control.
		memMaxBytes := int64(cfg.MemoryMB) * 1024 * 1024 * 3 / 2
		args = append(args,
			"--use_cgroupv2",
			"--cgroupv2_mount", mount,
			"--cgroup_mem_max", fmt.Sprintf("%d", memMaxBytes),
			"--cgroup_pids_max", fmt.Sprintf("%d", cfg.MaxPids),
		)
		// Use cgroup CPU bandwidth (cpu.max) instead of --max_cpus. The
		// --max_cpus flag is an affinity mask that pins the process to a
		// subset of cores — actively harmful under concurrency because the
		// kernel can't load-balance across the full CPU set. Bandwidth
		// limits (microseconds per period) are what fractional CPU means.
		if msPerSec := int(cfg.MaxCPUs * 1000); msPerSec > 0 {
			// nsjail --cgroup_cpu_ms_per_sec = ms of CPU per 1000 ms window.
			// Supports fractional CPUs: 0.5 → 500, 0.25 → 250.
			args = append(args,
				"--cgroup_cpu_ms_per_sec",
				fmt.Sprintf("%d", msPerSec),
			)
		}
	}

	if cfg.SeccompPolicy != "" {
		args = append(args, "--seccomp_string", cfg.SeccompPolicy)
	}

	// Inject env vars + secrets. nsjail takes --env KEY=VAL; an --env with
	// no '=' passes the host-side value through, which we never want for
	// security. Always format as KEY=VAL explicitly.
	for k, v := range cfg.Env {
