# Phase-1 NSTUN feasibility spike. Read-only w.r.t. the repo and the host:
# creates nothing outside this scratchpad and touches no firewall state.
S="$(cd "$(dirname "$0")" && pwd)"
NSJAIL="${NSJAIL:-/usr/local/bin/nsjail}"
ROOTFS="${ROOTFS:-/var/lib/orva/rootfs/node}"
CFG="$S/egress.cfg"
NODE=/usr/local/bin/node

printf 'nsjail=%s\nrootfs=%s\n\n' "$NSJAIL" "$ROOTFS"
printf 'nameserver 8.8.8.8\noptions timeout:2 attempts:1\n' > "$S/resolv.conf"

# Orva's real arg set (sandbox.go:199-206), with -Q -> -q so LOG_E is visible.
base=( -Mo --chroot "$ROOTFS" -T /tmp --rlimit_as max -q )

run_egress() { "$NSJAIL" --config "$CFG" "${base[@]}" --user_net \
    -R "$S/resolv.conf:/etc/resolv.conf" "$@" 2>&1; }

hr() { printf '\n--- %s\n' "$1"; }

