    -R "$S/resolv.conf:/etc/resolv.conf" "$@" 2>&1; }

hr() { printf '\n--- %s\n' "$1"; }

hr "T1 interfaces + routes + /proc (proves mount_proc survived, v4+v6 provisioned)"
run_egress -- /bin/sh -c 'ip -4 addr show eth0 2>/dev/null | grep -o "inet [0-9./]*"
ip -6 addr show eth0 2>/dev/null | grep -o "inet6 [0-9a-f:/]*" | head -2
echo "v4route: $(ip -4 route 2>/dev/null | head -1)"
echo "v6route: $(ip -6 route 2>/dev/null | grep default | head -1)"
echo "proc_entries: $(ls /proc 2>/dev/null | wc -l)"'

hr "T2 --env AFTER --config survives the CopyFrom wipe (must print last)"
run_egress --env ORVA_PROBE=survived -- /bin/sh -c 'echo "ORVA_PROBE=[$ORVA_PROBE]"'

hr "T3 --env BEFORE --config is WIPED (must print empty)"
"$NSJAIL" --env ORVA_PROBE=wiped --config "$CFG" "${base[@]}" --user_net \
    -- /bin/sh -c 'echo "ORVA_PROBE=[$ORVA_PROBE]"' 2>&1

hr "T4 default-ALLOW public TCP reachable (8.8.8.8:443)"
run_egress -- "$NODE" -e 'const s=require("net").connect(443,"8.8.8.8");
s.setTimeout(6000,()=>{console.log("ALLOW-TCP FAIL timeout");process.exit(1)});
s.on("connect",()=>{console.log("ALLOW-TCP ok");process.exit(0)});
s.on("error",e=>{console.log("ALLOW-TCP FAIL",e.code);process.exit(1)})'

hr "T5 DNS via the mounted resolver (UDP/53 carve-out)"
run_egress -- "$NODE" -e 'require("dns").resolve4("example.com",(e,a)=>{
console.log(e?"DNS FAIL "+e.code:"DNS ok "+a.join(","));process.exit(e?1:0)})'

hr "T6 blocked IPv4 /32 is REJECTed FAST (want ECONNREFUSED, not a timeout)"
t0=$(date +%s%N)
run_egress -- "$NODE" -e 'const s=require("net").connect(443,"1.1.1.1");
s.setTimeout(5000,()=>{console.log("V4-BLOCK FAIL timeout (DROP-like)");process.exit(1)});
s.on("connect",()=>{console.log("V4-BLOCK FAIL connected");process.exit(1)});
s.on("error",e=>{console.log("V4-BLOCK ok",e.code);process.exit(0)})'
printf 'elapsed_ms=%s\n' "$(( ($(date +%s%N)-t0)/1000000 ))"

hr "T7 cloud-metadata 169.254.169.254 blocked (shipped default rule)"
run_egress -- "$NODE" -e 'const s=require("net").connect(80,"169.254.169.254");
s.setTimeout(5000,()=>{console.log("METADATA timeout");process.exit(2)});
s.on("connect",()=>{console.log("METADATA FAIL connected");process.exit(1)});
s.on("error",e=>{console.log("METADATA ok",e.code);process.exit(0)})'

hr "T8 blocked IPv6 /32 (host has no v6 egress -> expect inconclusive)"
run_egress -- "$NODE" -e 'const s=require("net").connect(443,"2606:4700:4700::1111");
s.setTimeout(5000,()=>{console.log("V6-BLOCK timeout");process.exit(2)});
s.on("connect",()=>{console.log("V6-BLOCK FAIL connected");process.exit(1)});
s.on("error",e=>{console.log("V6-BLOCK got",e.code);process.exit(0)})'

hr "T9 network_mode=none stays isolated (no --config, no --user_net)"
"$NSJAIL" "${base[@]}" -- /bin/sh -c 'echo "ifaces: $(ip -o link 2>/dev/null | awk -F": " "{print \$2}" | tr "\n" " ")"
echo "default_route: [$(ip -4 route 2>/dev/null | head -1)]"' 2>&1
"$NSJAIL" "${base[@]}" -- "$NODE" -e 'const s=require("net").connect(443,"8.8.8.8");
s.setTimeout(4000,()=>{console.log("NONE ok (no egress: timeout)");process.exit(0)});
s.on("connect",()=>{console.log("NONE FAIL connected");process.exit(1)});
s.on("error",e=>{console.log("NONE ok (no egress:",e.code+")");process.exit(0)})' 2>&1

hr "T10 malformed config is FAIL-CLOSED (want exit 255)"
printf 'user_net { rule4 { action: NOPE } }\n' > "$S/bad.cfg"
"$NSJAIL" --config "$S/bad.cfg" "${base[@]}" -- /bin/true >/dev/null 2>&1
echo "exit=$? (want 255)"

hr "T11 FAIL-OPEN proof: prefix /64 on a v4 rule -> mask 0 -> match-any"
cat > "$S/evil.cfg" <<'EOF'
mount_proc: true
user_net { backend: NSTUN
  rule4 { direction: GUEST_TO_HOST action: REJECT proto: ANY dst_ip: "10.0.0.0/64" redirect_ip: "0.0.0.0" }
}
EOF
"$NSJAIL" --config "$S/evil.cfg" "${base[@]}" --user_net -R "$S/resolv.conf:/etc/resolv.conf" \
  -- "$NODE" -e 'const s=require("net").connect(443,"8.8.8.8");
s.setTimeout(5000,()=>{console.log("EVIL: timeout");process.exit(2)});
s.on("connect",()=>{console.log("EVIL: /64 IGNORED (rule dropped, still default-allow)");process.exit(0)});
s.on("error",e=>{console.log("EVIL: BUG CONFIRMED - /64 became match-any and blocked 8.8.8.8:",e.code);process.exit(0)})' 2>&1

hr "T12 no host firewall state was created by any of the above"
command -v nft >/dev/null 2>&1 && nft list ruleset 2>&1 | head -5 || echo "nft absent (nothing to check) - OK"
echo
echo "=== SPIKE COMPLETE ==="

