1	package database
2	
3	import (
4		"database/sql"
5		"fmt"
6		"time"
7	)
8	
9	// BlocklistRule is a single row in egress_blocklist. Default + suggested
10	// rules are seeded by Migrate(); custom rules come from the operator.
11	type BlocklistRule struct {
12		ID        int64     `json:"id"`
13		Kind      string    `json:"kind"`       // 'default' | 'suggested' | 'custom'
14		RuleType  string    `json:"rule_type"`  // 'cidr' | 'hostname' | 'wildcard'
15		Value     string    `json:"value"`
16		Label     string    `json:"label,omitempty"`
17		Enabled   bool      `json:"enabled"`
18		CreatedAt time.Time `json:"created_at"`
19		UpdatedAt time.Time `json:"updated_at"`
20	}
21	
22	// Allowed values used by validation in handlers + manager.
23	const (
24		BlocklistKindDefault   = "default"
25		BlocklistKindSuggested = "suggested"
26		BlocklistKindCustom    = "custom"
27	
28		BlocklistTypeCIDR     = "cidr"
29		BlocklistTypeHostname = "hostname"
30		BlocklistTypeWildcard = "wildcard"
31	)
32	
33	func ValidBlocklistRuleType(s string) bool {
34		switch s {
35		case BlocklistTypeCIDR, BlocklistTypeHostname, BlocklistTypeWildcard:
36			return true
37		}
38		return false
39	}
40	
41	// ListBlocklistRules returns every row, in (kind, id) order so the UI
42	// can render Default → Suggested → Custom without further sorting.
43	func (db *Database) ListBlocklistRules() ([]*BlocklistRule, error) {
44		rows, err := db.read.Query(`
45			SELECT id, kind, rule_type, value, COALESCE(label, ''), enabled,
46			       created_at, updated_at
47			FROM egress_blocklist
48			ORDER BY
49			    CASE kind WHEN 'default' THEN 0 WHEN 'suggested' THEN 1 ELSE 2 END,
50			    id ASC`)
51		if err != nil {
52			return nil, err
53		}
54		defer rows.Close()
55	
56		var out []*BlocklistRule
57		for rows.Next() {
58			r := &BlocklistRule{}
59			var enabled int
60			if err := rows.Scan(&r.ID, &r.Kind, &r.RuleType, &r.Value, &r.Label,
61				&enabled, &r.CreatedAt, &r.UpdatedAt); err != nil {
62				return nil, err
63			}
64			r.Enabled = enabled != 0
65			out = append(out, r)
66		}
67		return out, rows.Err()
68	}
69	
70	// ListEnabledBlocklistRules is the firewall manager's hot read.
71	func (db *Database) ListEnabledBlocklistRules() ([]*BlocklistRule, error) {
72		rows, err := db.read.Query(`
73			SELECT id, kind, rule_type, value, COALESCE(label, ''), enabled,
74			       created_at, updated_at
75			FROM egress_blocklist
76			WHERE enabled = 1`)
77		if err != nil {
78			return nil, err
79		}
80		defer rows.Close()
81	
82		var out []*BlocklistRule
83		for rows.Next() {
84			r := &BlocklistRule{}
85			var enabled int
86			if err := rows.Scan(&r.ID, &r.Kind, &r.RuleType, &r.Value, &r.Label,
87				&enabled, &r.CreatedAt, &r.UpdatedAt); err != nil {
88				return nil, err
89			}
90			r.Enabled = enabled != 0
91			out = append(out, r)
92		}
93		return out, rows.Err()
94	}
95	
96	// InsertCustomBlocklistRule adds an operator-entered rule. The kind is
97	// always 'custom'; default/suggested rows are seeded by Migrate().
98	func (db *Database) InsertCustomBlocklistRule(ruleType, value, label string, enabled bool) (*BlocklistRule, error) {
99		if !ValidBlocklistRuleType(ruleType) {
100			return nil, fmt.Errorf("invalid rule_type: %s", ruleType)
101		}
102		res, err := db.write.Exec(`
103			INSERT INTO egress_blocklist (kind, rule_type, value, label, enabled)
104			VALUES ('custom', ?, ?, NULLIF(?, ''), ?)`,
105			ruleType, value, label, boolToInt(enabled))
106		if err != nil {
107			return nil, err
108		}
109		id, _ := res.LastInsertId()
110		return db.GetBlocklistRule(id)
111	}
112	
113	func (db *Database) GetBlocklistRule(id int64) (*BlocklistRule, error) {
114		r := &BlocklistRule{}
